'use client';

import { useRef, type JSX, type ReactNode } from 'react';
import {
  Button as RACButton,
  DateInput,
  DatePicker as RACDatePicker,
  DateRangePicker as RACDateRangePicker,
  DateSegment,
  Dialog,
  Popover,
  composeRenderProps,
  type DatePickerProps as RACDatePickerProps,
  type DateRangePickerProps as RACDateRangePickerProps,
  type DateValue,
  type ValidationResult,
} from 'react-aria-components';
import { IconCalendar } from '@tabler/icons-react';
import { Calendar, RangeCalendar } from './calendar';
import { Description, FieldError, FieldGroup, Label } from './text-field';
import styles from './date-picker.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

/**
 * Overlays portal to <body>, outside any ThemeScope. When the popover mounts, copy the trigger's scope
 * attributes (theme, scheme, density — and dir/lang if React Aria hasn't set them) onto it, so the popover
 * is a scope of its own and renders with the same tokens. Same approach as dialog.tsx.
 */
const SCOPE_ATTRS = ['data-strata-theme', 'data-strata-scheme', 'data-strata-density'] as const;
function mirrorScope(overlay: HTMLElement | null, source: Element | null): void {
  if (!overlay || !source || overlay.contains(source)) return;
  for (const name of SCOPE_ATTRS) {
    // Look each attribute up on its own: a single-tenant app themes :root and scopes only the scheme.
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
  for (const name of ['dir', 'lang']) {
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value && !overlay.hasAttribute(name)) overlay.setAttribute(name, value);
  }
}

interface FieldTextProps {
  /** Visible label. Pass `aria-label` instead only when a visible label is truly impossible. */
  label?: ReactNode;
  /** Help text under the field, e.g. the expected format or allowed range. */
  description?: ReactNode;
  /** Shown when the field is invalid. A string, or a function of RAC's validation result. */
  errorMessage?: string | ((validation: ValidationResult) => string);
}

export interface DatePickerProps<T extends DateValue> extends RACDatePickerProps<T>, FieldTextProps {}

function renderDateInput(slot?: 'start' | 'end'): JSX.Element {
  return (
    <DateInput slot={slot} className={styles.input}>
      {(segment) => <DateSegment segment={segment} className={styles.segment} />}
    </DateInput>
  );
}

/**
 * A date field typed segment by segment (locale order), with a button that opens a calendar.
 * Keyboard: ←/→ move between segments, ↑/↓ change the value, type digits to fill,
 * Alt+↓ opens the calendar.
 */
export function DatePicker<T extends DateValue>({
  label,
  description,
  errorMessage,
  shouldForceLeadingZeros = true,
  className,
  ...props
}: DatePickerProps<T>): JSX.Element {
  const groupRef = useRef<HTMLDivElement>(null);
  return (
    <RACDatePicker<T>
      {...props}
      shouldForceLeadingZeros={shouldForceLeadingZeros}
      className={composeRenderProps(className, (c) => cx(styles.field, c))}
    >
      {label != null && <Label isRequired={props.isRequired}>{label}</Label>}
      <FieldGroup ref={groupRef} className={styles.control}>
        {renderDateInput()}
        <RACButton className={styles.button}>
          <IconCalendar aria-hidden className={styles.buttonIcon} />
        </RACButton>
      </FieldGroup>
      {description != null && <Description>{description}</Description>}
      <FieldError>{errorMessage}</FieldError>
      <Popover offset={4} ref={(node) => mirrorScope(node, groupRef.current)} className={styles.popover}>
        <Dialog className={styles.dialog}>
          <Calendar />
        </Dialog>
      </Popover>
    </RACDatePicker>
  );
}

export interface DateRangePickerProps<T extends DateValue> extends RACDateRangePickerProps<T>, FieldTextProps {
  /** How many months the calendar shows side by side. */
  visibleMonths?: number;
}

/** Two date fields (start and end) sharing one calendar popover for picking a range. */
export function DateRangePicker<T extends DateValue>({
  label,
  description,
  errorMessage,
  visibleMonths = 1,
  shouldForceLeadingZeros = true,
  className,
  ...props
}: DateRangePickerProps<T>): JSX.Element {
  const groupRef = useRef<HTMLDivElement>(null);
  return (
    <RACDateRangePicker<T>
      {...props}
      shouldForceLeadingZeros={shouldForceLeadingZeros}
      className={composeRenderProps(className, (c) => cx(styles.field, c))}
    >
      {label != null && <Label isRequired={props.isRequired}>{label}</Label>}
      <FieldGroup ref={groupRef} className={styles.control}>
        {renderDateInput('start')}
        <span aria-hidden className={styles.dash}>
          –
        </span>
        {renderDateInput('end')}
        <RACButton className={styles.button}>
          <IconCalendar aria-hidden className={styles.buttonIcon} />
        </RACButton>
      </FieldGroup>
      {description != null && <Description>{description}</Description>}
      <FieldError>{errorMessage}</FieldError>
      <Popover offset={4} ref={(node) => mirrorScope(node, groupRef.current)} className={styles.popover}>
        <Dialog className={styles.dialog}>
          <RangeCalendar visibleDuration={{ months: visibleMonths }} />
        </Dialog>
      </Popover>
    </RACDateRangePicker>
  );
}

/* DatePicker + DateRangePicker. The box is text-field's FieldGroup, so it matches every other field. */
.field {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--strata-space-2);
  min-inline-size: 0;
}

/* text-field's FieldGroup draws the box; tighten its end padding so the calendar button sits in the corner. */
.field .control {
  gap: var(--strata-space-1);
  padding-inline-end: var(--strata-space-1);
}

.input {
  display: flex;
  align-items: center;
  min-inline-size: 0;
  /* Segments are 24px targets with centred digits; pull the first one back so its digits line up with
     the text of other fields. */
  margin-inline-start: calc(var(--strata-space-1) * -1);
  overflow: hidden;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* The (last) date input fills the box, so a click on empty space lands on it and RAC focuses a segment. */
.control > .input:last-of-type {
  flex: 1;
}

/* Each editable segment is its own 24×24 target (WCAG 2.5.8 — adjacent segments get no spacing exception).
   24px fits inside the compact 32px box, so the field height never changes. */
.segment {
  box-sizing: border-box;
  display: inline-block;
  min-inline-size: var(--strata-space-6);
  min-block-size: var(--strata-space-6);
  padding-inline: calc(var(--strata-space-1) / 2);
  border-radius: min(var(--strata-radius-field), var(--strata-space-1));
  color: var(--strata-color-text-default);
  line-height: var(--strata-space-6);
  text-align: center;
  caret-color: transparent;
  outline: none;
  forced-color-adjust: none;
}
.segment[data-type='literal'] {
  min-inline-size: 0;
  padding-inline: 0;
  color: var(--strata-color-text-subtle);
}
.segment[data-placeholder] {
  color: var(--strata-color-text-subtle);
}
.segment[data-focused] {
  background: var(--strata-color-surface-selected);
  color: var(--strata-color-text-default);
}
.segment[data-disabled],
.segment[data-disabled][data-placeholder] {
  color: var(--strata-color-text-disabled);
}

.dash {
  flex: none;
  padding-inline: var(--strata-space-1);
  color: var(--strata-color-text-subtle);
}

.button {
  box-sizing: border-box;
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  inline-size: calc(var(--strata-control-height) - var(--strata-space-2));
  block-size: calc(var(--strata-control-height) - var(--strata-space-2));
  min-inline-size: var(--strata-space-6);
  min-block-size: var(--strata-space-6);
  margin-inline-start: auto;
  padding: 0;
  border: 0;
  border-radius: min(var(--strata-radius-button), var(--strata-space-2));
  background: transparent;
  color: var(--strata-color-text-subtle);
  cursor: default;
  outline: none;
}
.button[data-hovered] {
  background: color-mix(in oklab, var(--strata-color-text-default) 6%, transparent);
  color: var(--strata-color-text-default);
}
/* RAC keeps the button "pressed" while the calendar is open; only tint it for a real press. */
.button[data-pressed][data-hovered] {
  background: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}
.button[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}
.button[data-disabled] {
  color: var(--strata-color-text-disabled);
  background: transparent;
}
.buttonIcon {
  inline-size: 1.15em;
  block-size: 1.15em;
  stroke-width: 2;
}

.popover {
  box-sizing: border-box;
  overflow: auto;
  border: 1px solid var(--strata-color-border-default);
  border-radius: var(--strata-radius-container);
  background: var(--strata-color-surface-raised);
  color: var(--strata-color-text-default);
  box-shadow: var(--strata-shadow-overlay);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  outline: none;
}
.dialog {
  outline: none;
}

@media (prefers-reduced-motion: no-preference) {
  .popover[data-entering] {
    animation: popover-in var(--strata-motion-duration-fast) var(--strata-motion-easing);
  }
  .popover[data-exiting] {
    animation: popover-out var(--strata-motion-duration-fast) var(--strata-motion-easing) forwards;
  }
}
.popover[data-placement='bottom'] {
  --popover-slide: 0 calc(var(--strata-space-1) * -1);
}
.popover[data-placement='top'] {
  --popover-slide: 0 var(--strata-space-1);
}
.popover[data-placement='left'] {
  --popover-slide: var(--strata-space-1) 0;
}
.popover[data-placement='right'] {
  --popover-slide: calc(var(--strata-space-1) * -1) 0;
}
@keyframes popover-in {
  from {
    opacity: 0;
    translate: var(--popover-slide, 0 0);
  }
}
@keyframes popover-out {
  to {
    opacity: 0;
    translate: var(--popover-slide, 0 0);
  }
}
